import { Context } from 'vibelang/context';
import { Layer } from 'vibelang/provider';
abstract class Db extends Context { abstract value(): number }
abstract class Cfg extends Context { abstract value(): number }
function readDb(): number { return Db.context().value() }
function readCfg(): number { return Cfg.context().value() }

cases.body:
const trace: string[] = [];
async function failing(): Promise<Result<number, Error>> { try { throw new Error('failed') } finally { await Promise.resolve(); trace.push(String(readDb())) } }
export async function main(): Promise<string[]> { return await Layer.provide(Layer.succeed(Db, { value: () => 7 }), async () => { const result = await failing(); return [...trace, result.match({ ok: value => String(value), error: error => error.message })] }) }

async function answer(): Promise<number> { await Promise.resolve(); return readDb() }
async function run(flag: boolean): Promise<string> { const value = await Layer.provide(Layer.succeed(Db, { value: () => 7 }), () => flag ? answer() : 3); return String(value) }
export async function main(): Promise<string[]> { return [await run(true), await run(false)] }

function children(): Promise<number>[] { return [Promise.resolve(1)] }
function mixed(flag: boolean): Promise<number> | Promise<number>[] { return flag ? Promise.resolve(2) : children() }
export async function main(flag: boolean): Promise<string[]> { await mixed(flag); return [] }
